var goodBinaryStrings = function(minLength, maxLength, oneGroup, zeroGroup) {
    const MOD = 1e9 + 7;
    const pre = new Array(maxLength + 2).fill(0);
    const dp = new Array(maxLength + 1).fill(0);
    dp[0] = 1; pre[1] = 1;
    for (let i = 1; i <= maxLength; i++) {
        let cur = 0;
        if (i >= oneGroup) cur += pre[i - oneGroup + 1] - pre[i - oneGroup];
        if (i >= zeroGroup) cur += pre[i - zeroGroup + 1] - pre[i - zeroGroup];
        dp[i] = ((cur % MOD) + MOD) % MOD;
        pre[i + 1] = (pre[i] + dp[i]) % MOD;
    }
    return ((pre[maxLength + 1] - pre[minLength]) % MOD + MOD) % MOD;
};
